import axios from "axios"
import React, { useState, useEffect } from "react"
import { useLocation, Link } from 'react-router-dom'


const MemberInfo = () => {
    const [member, setMember] = useState()

    const location = useLocation()
    const memberId = location.pathname.split("/")[2] // gets the member id

    useEffect(() => {
        const fetchMember = async () => {
            try {
                const res = await axios.get(`http://localhost:8800/member/${memberId}`)
                setMember(res.data)
            } catch (err) {
                console.log(err)
            }
        }
        fetchMember()
    }, [memberId])

    console.log(member)

    const handleChange = async (event) => {
        setMember((prev) => ({ ...prev, [event.target.name]: event.target.value })) 
    }

    const handleClick = async (event) => {
        event.preventDefault()

        try {
            await axios.put(`http://localhost:8800/member/${memberId}`, member)
        } catch (err) {
            console.log(err)
        }
    }

    return (
    <div>
      <h1>Members</h1>
      <div className="members">
        {member.map((member) => (
          <div key={member.id} className="member">
            <h2>{member.firstname} {member.lastname}</h2>
            <button className="memberInfo">
              <Link to={`/memberInfo/${member.id}`} style={{ color: "inherit", textDecoration: "none" }}>
                Info
              </Link>
            </button>
            <button className="delete" onClick={() => handleDelete(member.id)}>Delete</button>

            <p>Membership: {member.membership}</p>
            <p>Age: {member.age}</p>

          </div>
        ))}
      </div>

      <button className="addHome">
        <Link to="/add" style={{ color: "inherit", textDecoration: "none" }}>
          Add new member
        </Link>
      </button>
    </div>
  )
}

export default MemberInfo
